   <small><?= e($event['repository']) ?><?php if($event['metadata']['branch']??null): ?> · <?= e($event['metadata']['branch']) ?><?php endif; ?><?php if($event['metadata']['target_branch']??null): ?> → <?= e($event['metadata']['target_branch']) ?><?php endif; ?><?php if($event['commit_sha'] && $kind!=='pull_request'): ?> · <?= e(substr($event['commit_sha'],0,12)) ?><?php endif; ?></small>
   <small><?php if($event['metadata']['author']??null): ?><?= e($event['metadata']['author']) ?> · <?php endif; ?><?= ($event['metadata']['date_known']??true)?e($event['occurred_at']):'Date non fournie par le fournisseur' ?></small>
   <?php if($kind==='pull_request'): ?><div class="git-pr-summary">
    <?php if($stats): ?><button type="button" class="button subtle small-button" data-git-files="<?= (int)$event['id'] ?>"><?= (int)$stats['file_count'] ?> fichier(s) modifié(s)</button><span class="git-lines-added"><?= $stats['additions']===null?'Ajouts non fournis':'+'.(int)$stats['additions'] ?></span><span class="git-lines-deleted"><?= $stats['deletions']===null?'Suppressions non fournies':'−'.(int)$stats['deletions'] ?></span><small><?= (int)$stats['commit_count'] ?> commit(s)<?= $stats['commits_complete']?'':' · liste partielle' ?> · relevé du <?= e($stats['fetched_at']) ?><?php if($stats['revision']!==GitPullRequest::revision($event)): ?> · à actualiser<?php endif; ?></small><?php else: ?><small>Commits et fichiers à récupérer.</small><?php endif; ?>
    <?php if($user['role']!=='viewer'): ?><button type="button" class="button subtle small-button" data-git-sync-pr="<?= (int)$event['id'] ?>"><?= $stats?'Actualiser les détails':'Récupérer les commits et fichiers' ?></button><?php endif; ?>
   </div><?php endif; ?>
  </div></article><?php endforeach; ?>
  <?php if(!$kindEvents): ?><p class="muted">Aucun élément reçu pour le moment.</p><?php endif; ?>
 </details><?php endforeach; ?>
 <?php if(count($events)===100): ?><small>Les 100 éléments liés les plus récents sont affichés.</small><?php endif; ?>
</section>
